import{_ as t,c as e,o as a,a4 as s}from"./chunks/framework.P4k6vdAm.js";const g=JSON.parse('{"title":"What is AireGlu?","description":"","frontmatter":{},"headers":[],"relativePath":"docs/overview/index.md","filePath":"docs/overview/index.md","lastUpdated":1793099931000}'),o={name:"docs/overview/index.md"},r=s('<h1 id="what-is-aireglu" tabindex="-1">What is AireGlu? <a class="header-anchor" href="#what-is-aireglu" aria-label="Permalink to &quot;What is AireGlu?&quot;">​</a></h1><p>AireGlu is the low-code integration engine of the AireBlocks suite. It lets you build <strong>endpoints</strong>: HTTP APIs that receive data, transform it, and pass it on to other systems, without writing or hosting any code yourself.</p><p>A typical endpoint might:</p><ul><li>receive a form submission from <a href="https://docs.forms.aireinnovate.com/" target="_blank" rel="noreferrer">AireForms</a>,</li><li>reshape the data with a mapping or <a href="/docs/building/liquid.html">Liquid</a> template,</li><li>send it to a third-party API, and</li><li>email a confirmation to the person who submitted it.</li></ul><h2 id="what-you-can-do-with-it" tabindex="-1">What you can do with it <a class="header-anchor" href="#what-you-can-do-with-it" aria-label="Permalink to &quot;What you can do with it&quot;">​</a></h2><table><thead><tr><th>You want to...</th><th>Use</th></tr></thead><tbody><tr><td>Call external APIs, or your own endpoints</td><td><a href="/docs/tasks/http-request.html">HTTP Request</a> and <a href="/docs/tasks/aireglu-endpoint-request.html">AireGlu Endpoint Request</a> tasks</td></tr><tr><td>Transform data between formats and shapes</td><td><a href="/docs/tasks/mapping.html">Mapping</a> task and <a href="/docs/building/liquid.html">Liquid</a></td></tr><tr><td>Send messages</td><td><a href="/docs/tasks/email.html">Email</a>, <a href="/docs/tasks/sms.html">SMS</a>, <a href="/docs/tasks/mesh-message.html">MESH</a> and <a href="/docs/tasks/fax.html">Fax</a> tasks</td></tr><tr><td>Generate documents and tokens</td><td><a href="/docs/tasks/pdf.html">PDF</a> and <a href="/docs/tasks/jwt.html">JWT</a> tasks</td></tr><tr><td>Run something on a schedule</td><td><a href="/docs/triggering/jobs.html">Jobs</a></td></tr><tr><td>React to incoming emails, SMS or MESH messages</td><td><a href="/docs/triggering/receivers.html">Receivers</a></td></tr><tr><td>Process many items asynchronously</td><td><a href="/docs/triggering/batch-invocation.html">Batch invocation</a></td></tr><tr><td>Let AI assistants and agents use your endpoints</td><td><a href="/docs/mcp-servers/">MCP Servers</a> and <a href="/docs/agents/">Agents</a></td></tr><tr><td>Add behaviour AireGlu doesn&#39;t have out of the box</td><td><a href="/docs/developers/adapters.html">Adapters</a></td></tr></tbody></table><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><strong>New to AireGlu?</strong> Read <a href="/docs/overview/key-concepts.html">Key Concepts</a> for the ideas the rest of the docs build on, then follow <a href="/docs/getting-started/">Your First Endpoint</a>.</li><li><strong>Building something specific?</strong> Start from <a href="/docs/building/endpoint-settings.html">Endpoint Settings</a> and the <a href="/docs/tasks/">Tasks</a> overview.</li><li><strong>Unfamiliar term?</strong> Check the <a href="/docs/overview/glossary.html">Glossary</a>.</li></ul>',8),i=[r];function d(n,h,l,c,m,u){return a(),e("div",null,i)}const p=t(o,[["render",d]]);export{g as __pageData,p as default};
